using System.Web.Script.Services; using System.Web.Services;
namespace WamoApp.Admin { public partial class CollectionsPage : WamoApp.AdminPage { [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object GetList() { SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("Collections", "View"); return AdminDataService.GetList("Collections"); } [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object GetDefinition() { SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("Collections", "View"); return AdminDataService.GetDefinitionMetadata("Collections"); } [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object DeleteRecord(string id) { SecurityHelper.ValidateCsrfOrThrow(); SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("Collections", "Delete"); return AdminDataService.Delete("Collections", id); } } }
